<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { ArrowRight, Crosshair, GitBranch } from 'lucide-vue-next'
import { useRoute, useRouter } from 'vue-router'
import AsyncState from '@/components/shared/AsyncState.vue'
import PageHeader from '@/components/shared/PageHeader.vue'
import RoadmapDraftNode from '@/components/roadmap/RoadmapDraftNode.vue'
import { useRoadmapStore } from '@/stores/roadmap'

const route = useRoute(); const router = useRouter(); const roadmap = useRoadmapStore(); const selectedStart = ref('')
const draft = computed(() => roadmap.draft); const roots = computed(() => draft.value?.nodes.filter((node) => !node.parentId).sort((a, b) => a.position - b.position) ?? [])
const startOptions = computed(() => draft.value?.executionProposal?.options ?? []); const recommendedStart = computed(() => draft.value?.executionProposal?.recommendedUnitKey ?? '')
function nodeTitle(key: string) { return draft.value?.nodes.find((node) => node.nodeKey === key)?.title ?? key }
onMounted(async () => { await roadmap.loadDraft(String(route.params.roadmapId)); selectedStart.value = recommendedStart.value })
async function confirm() { if (!draft.value) return; await roadmap.confirm(draft.value.id, draft.value.revision, selectedStart.value || undefined); await router.push({ name: 'overview' }) }
</script>

<template>
  <div class="page roadmap-preview-page"><AsyncState :loading="roadmap.loading" :error="roadmap.error"><template #default><PageHeader eyebrow="02 · Route draft" title="这是一张可以调整的长期路线图。" description="路线图描述能力之间的关系，确认后会从中切出当前可执行的学习计划。" :meta="[`${draft?.progress.total ?? 0} 个动态节点`, '路线草案', '确认后才切换正式计划']" />
    <template v-if="draft"><section class="draft-summary"><div><small>你的目标</small><h2>{{ draft.goal }}</h2><p>当前草案会优先打开一条能力分支，其余节点保留在长期路线中。</p></div><div class="progress-stat"><strong>{{ draft.progress.total }}</strong><span>个路线节点</span></div></section>
    <p class="dynamic-note">这份路线依据当前规划对话动态生成；想改变方向时，请请求规划助手生成调整草案。</p>
    <section v-if="startOptions.length" class="start-choice" aria-labelledby="start-choice-title"><div class="section-label"><Crosshair :size="15" aria-hidden="true" /><span id="start-choice-title">先决定从哪里开始</span></div><p>路线图是长期能力树，确认时需要选择本周期的第一个执行节点。其他节点不会被丢弃。</p><div class="start-options"><label v-for="option in startOptions" :key="option.unitKey" class="start-option" :class="{ selected: selectedStart === option.unitKey }"><input v-model="selectedStart" type="radio" name="start-unit" :value="option.unitKey" /><span><strong>{{ nodeTitle(option.unitKey) }}</strong><em>{{ option.unitKey === recommendedStart ? 'Planner 建议' : '可选起点' }}</em><small>{{ option.rationale.join('；') }}</small><small>后续：{{ option.orderedInitialUnitKeys.map(nodeTitle).join(' → ') }}</small></span></label></div></section>
    <section class="roadmap-draft" aria-labelledby="draft-title"><div class="section-label"><GitBranch :size="15" aria-hidden="true" /><span id="draft-title">能力树草案</span></div><p class="tree-intro">路线按生成结果展开；点击任意节点可查看完成标准、安排依据和下一层能力。</p><div class="draft-tree"><RoadmapDraftNode v-for="root in roots" :key="root.id" :node="root" :nodes="draft.nodes" /></div></section>
    <section class="confirm-bar"><div><strong>确认这张路线图</strong><span>确认后会归档旧路线，并保留历史实践与文章。</span></div><button class="primary-button" type="button" :disabled="startOptions.length > 0 && !selectedStart" @click="confirm">确认并进入总览 <ArrowRight :size="14" aria-hidden="true" /></button></section></template>
  </template></AsyncState></div>
</template>

<style scoped>
.roadmap-preview-page { max-width: 1120px; }.draft-summary { display: flex; align-items: end; justify-content: space-between; gap: 22px; margin-top: 28px; padding: 19px 0; border-top: 2px solid var(--orange); border-bottom: 1px solid var(--line); }.draft-summary small, .progress-stat span { color: #7e8781; font: 9px var(--mono); }.draft-summary h2 { margin: 7px 0 0; color: var(--ink); font: 400 23px var(--serif); }.draft-summary p { margin: 7px 0 0; color: var(--muted); font-size: 11px; }.progress-stat { display: flex; align-items: baseline; gap: 7px; flex: 0 0 auto; }.progress-stat strong { color: var(--orange); font: 400 36px var(--serif); }.adjust-strip { display: flex; align-items: center; flex-wrap: wrap; gap: 9px; margin-top: 20px; padding: 11px 0; border-bottom: 1px solid var(--line); }.adjust-strip > div { display: inline-flex; align-items: center; gap: 7px; margin-right: auto; color: var(--blue); }.adjust-strip > div span { color: var(--muted); font-size: 10px; }.adjust-strip select { min-height: 32px; border: 1px solid var(--line); background: var(--paper); color: #52605a; font-size: 10px; }.roadmap-draft { margin-top: 28px; }.tree-intro { margin: 8px 0 14px; color: var(--muted); font-size: 10px; line-height: 1.5; }.draft-tree { border-top: 2px solid var(--blue); padding: 0 15px; background: var(--paper); }.section-label { display: flex; align-items: center; gap: 7px; color: var(--blue); font: 9px var(--mono); text-transform: uppercase; }.start-choice { margin-top: 24px; padding: 15px 0; border-top: 2px solid var(--green); border-bottom: 1px solid var(--line); }.start-choice > p { margin: 8px 0 12px; color: var(--muted); font-size: 10px; }.start-options { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }.start-option { display: flex; gap: 9px; min-height: 100%; padding: 12px; border: 1px solid var(--line); background: var(--paper); cursor: pointer; }.start-option.selected { border-color: var(--green); background: var(--green-soft); }.start-option input { margin-top: 3px; accent-color: var(--green); }.start-option strong, .start-option em, .start-option small { display: block; }.start-option strong { color: var(--ink); font: 400 15px var(--serif); }.start-option em { margin-top: 4px; color: var(--green); font: 9px var(--mono); font-style: normal; }.start-option small { margin-top: 7px; color: var(--muted); font-size: 10px; line-height: 1.45; }.confirm-bar { display: flex; align-items: center; justify-content: space-between; gap: 20px; margin-top: 27px; padding: 15px 0; border-top: 2px solid var(--orange); }.confirm-bar strong { display: block; color: var(--ink); font: 400 17px var(--serif); }.confirm-bar span { display: block; margin-top: 5px; color: var(--muted); font-size: 10px; }.primary-button, .ghost-button { display: inline-flex; align-items: center; gap: 6px; min-height: 34px; padding: 8px 11px; border: 1px solid #b66844; background: var(--orange-soft); color: #995436; font-size: 10px; cursor: pointer; }.ghost-button { border-color: var(--line); background: var(--paper); color: var(--blue); }.primary-button:disabled, .ghost-button:disabled { opacity: .55; cursor: wait; }
 @media (max-width: 820px) { .draft-summary, .confirm-bar { align-items: stretch; flex-direction: column; }.confirm-bar button { justify-content: center; }.start-options { grid-template-columns: 1fr; } }
</style>
